def coerce_priority_lax(value):
    candidate = value
    if isinstance(candidate, str):
        candidate = candidate.strip()
    try:
        parsed = int(candidate)
    except (TypeError, ValueError):
        return None
    if 1 <= parsed <= 5:
        return parsed
    return None

def coerce_priority_strict(value):
    if type(value) is not int:
        return None
    if 1 <= value <= 5:
        return value
    return None

def build_ticket_output(payload):
    if not isinstance(payload, dict):
        return None

    title = payload.get('title')
    if not isinstance(title, str):
        return None
    title = title.strip()
    if not title:
        return None

    raw_priority = payload.get('priority')
    try:
        priority = int(raw_priority)
    except (TypeError, ValueError):
        return None
    if not (1 <= priority <= 5):
        return None

    owner = payload.get('owner', 'unassigned')
    if owner is not None and not isinstance(owner, str):
        return None

    return {
        'title': title,
        'priority': priority,
        'owner': owner,
    }

def collect_ticket_errors(payload):
    errors = []
    if not isinstance(payload, dict):
        return [
            {'field': 'title', 'code': 'title_invalid'},
            {'field': 'priority', 'code': 'priority_invalid'},
        ]

    title = payload.get('title')
    if not isinstance(title, str) or not title.strip():
        errors.append({'field': 'title', 'code': 'title_invalid'})

    raw_priority = payload.get('priority')
    try:
        parsed_priority = int(raw_priority)
        priority_ok = 1 <= parsed_priority <= 5
    except (TypeError, ValueError):
        priority_ok = False
    if not priority_ok:
        errors.append({'field': 'priority', 'code': 'priority_invalid'})

    if 'owner' in payload:
        owner = payload.get('owner')
        if owner is not None and not isinstance(owner, str):
            errors.append({'field': 'owner', 'code': 'owner_invalid'})

    return errors

def dump_ticket(ticket, include_none=False):
    result = {
        'title': ticket.get('title'),
        'priority': ticket.get('priority'),
    }

    owner = ticket.get('owner')
    if owner is not None or include_none:
        result['owner'] = owner

    tags = ticket.get('tags')
    if isinstance(tags, list) and len(tags) > 0:
        result['tags'] = list(tags)

    return result
